/** Resolves a current slug, or a slug still within its post-rename hold. */
export async function findOrgBySlug(
  slug: string,
  now: Date = new Date(),
): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
