/** Whether `orgId` may take `slug`: nobody else holds it, currently or retired. */
export async function isOrgSlugAvailable(
  orgId: OrgId,
  slug: string,
  now: Date = new Date(),
): Promise<boolean> {
  const db = getDb();
  const current = db
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (current) return false;

  const retired = db
    .select()
    .from(organizationRetiredSlugs)
    .where(eq(organizationRetiredSlugs.slug, slug))
    .get();
  return !(
    retired &&
    retired.orgId !== orgId &&
    isHoldActive(retired.retiredAt, now)
  );
}

/**
 * Switches the current slug and retires the one replaced, atomically. The
 * caller has already checked availability.
 */
export async function changeOrgSlug(
  orgId: OrgId,
  slug: string,
  now: Date = new Date(),
): Promise<Organization> {
  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);

    tx.delete(organizationRetiredSlugs)
      .where(
        and(
          eq(organizationRetiredSlugs.slug, slug),
          eq(organizationRetiredSlugs.orgId, orgId),
        ),
      )
      .run();

    const row = tx
      .update(organizations)
      .set({ slug })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    tx.insert(organizationRetiredSlugs)
      .values({
        slug: current.slug,
        orgId,
        retiredAt: toIsoTimestamp(now),
      })
      .onConflictDoUpdate({
        target: organizationRetiredSlugs.slug,
        set: { orgId, retiredAt: toIsoTimestamp(now) },
      })
      .run();

    return toOrganization(row);
  });
}
